7	import React from 'react';
8	import { Text } from 'ink';
9	import { theme } from '../semantic-colors.js';
10	import { debugLogger } from '@google/gemini-cli-core';
11	import { stripUnsafeCharacters } from './textUtils.js';
12	
13	// Constants for Markdown parsing
14	const BOLD_MARKER_LENGTH = 2; // For "**"
15	const ITALIC_MARKER_LENGTH = 1; // For "*" or "_"
16	const STRIKETHROUGH_MARKER_LENGTH = 2; // For "~~")
17	const INLINE_CODE_MARKER_LENGTH = 1; // For "`"
18	const UNDERLINE_TAG_START_LENGTH = 3; // For "<u>"
19	const UNDERLINE_TAG_END_LENGTH = 4; // For "</u>"
20	
21	interface RenderInlineProps {
22	  text: string;
23	  defaultColor?: string;
24	}
25	
26	const RenderInlineInternal: React.FC<RenderInlineProps> = ({
27	  text: rawText,
28	  defaultColor,
29	}) => {
30	  const text = stripUnsafeCharacters(rawText);
31	  const baseColor = defaultColor ?? theme.text.primary;
32	  // Early return for plain text without markdown or URLs
33	  if (!/[*_~`<[https?:]/.test(text)) {
34	    return <Text color={baseColor}>{text}</Text>;
35	  }
36	
37	  const nodes: React.ReactNode[] = [];
38	  let lastIndex = 0;
39	  const inlineRegex =
40	    /(\*\*.*?\*\*|\*.*?\*|_.*?_|~~.*?~~|\[.*?\]\(.*?\)|`+.+?`+|<u>.*?<\/u>|https?:\/\/\S+)/g;
41	  let match;
42	
43	  while ((match = inlineRegex.exec(text)) !== null) {
44	    if (match.index > lastIndex) {
45	      nodes.push(
46	        <Text key={`t-${lastIndex}`} color={baseColor}>
47	          {text.slice(lastIndex, match.index)}
48	        </Text>,
49	      );
50	    }
51	
52	    const fullMatch = match[0];
53	    let renderedNode: React.ReactNode = null;
54	    const key = `m-${match.index}`;
55	
56	    try {
57	      if (
58	        fullMatch.startsWith('**') &&
59	        fullMatch.endsWith('**') &&
60	        fullMatch.length > BOLD_MARKER_LENGTH * 2
61	      ) {
62	        renderedNode = (
63	          <Text key={key} bold color={baseColor}>
64	            {fullMatch.slice(BOLD_MARKER_LENGTH, -BOLD_MARKER_LENGTH)}
65	          </Text>
66	        );
67	      } else if (
68	        fullMatch.length > ITALIC_MARKER_LENGTH * 2 &&
69	        ((fullMatch.startsWith('*') && fullMatch.endsWith('*')) ||
70	          (fullMatch.startsWith('_') && fullMatch.endsWith('_'))) &&
71	        !/\w/.test(text.substring(match.index - 1, match.index)) &&
72	        !/\w/.test(
73	          text.substring(inlineRegex.lastIndex, inlineRegex.lastIndex + 1),
74	        ) &&
75	        !/\S[./\\]/.test(text.substring(match.index - 2, match.index)) &&
76	        !/[./\\]\S/.test(
77	          text.substring(inlineRegex.lastIndex, inlineRegex.lastIndex + 2),
78	        )
79	      ) {
80	        renderedNode = (
81	          <Text key={key} italic color={baseColor}>
82	            {fullMatch.slice(ITALIC_MARKER_LENGTH, -ITALIC_MARKER_LENGTH)}
83	          </Text>
84	        );
85	      } else if (
86	        fullMatch.startsWith('~~') &&
87	        fullMatch.endsWith('~~') &&
88	        fullMatch.length > STRIKETHROUGH_MARKER_LENGTH * 2
89	      ) {
90	        renderedNode = (
91	          <Text key={key} strikethrough color={baseColor}>
92	            {fullMatch.slice(
93	              STRIKETHROUGH_MARKER_LENGTH,
94	              -STRIKETHROUGH_MARKER_LENGTH,
95	            )}
96	          </Text>
97	        );
98	      } else if (
99	        fullMatch.startsWith('`') &&
100	        fullMatch.endsWith('`') &&
101	        fullMatch.length > INLINE_CODE_MARKER_LENGTH
102	      ) {
103	        const codeMatch = fullMatch.match(/^(`+)(.+?)\1$/s);
104	        if (codeMatch && codeMatch[2]) {
105	          renderedNode = (
106	            <Text key={key} color={theme.text.accent}>
107	              {codeMatch[2]}
108	            </Text>
109	          );
110	        }
111	      } else if (
112	        fullMatch.startsWith('[') &&
113	        fullMatch.includes('](') &&
114	        fullMatch.endsWith(')')
115	      ) {
116	        const linkMatch = fullMatch.match(/\[(.*?)\]\((.*?)\)/);
117	        if (linkMatch) {
118	          const linkText = linkMatch[1];
119	          const url = linkMatch[2];
120	          renderedNode = (
121	            <Text key={key} color={baseColor}>
122	              {linkText}
123	              <Text color={theme.text.link}> ({url})</Text>
124	            </Text>
125	          );
126	        }
127	      } else if (
128	        fullMatch.startsWith('<u>') &&
129	        fullMatch.endsWith('</u>') &&
130	        fullMatch.length >
131	          UNDERLINE_TAG_START_LENGTH + UNDERLINE_TAG_END_LENGTH - 1 // -1 because length is compared to combined length of start and end tags
132	      ) {
133	        renderedNode = (
134	          <Text key={key} underline color={baseColor}>
135	            {fullMatch.slice(
136	              UNDERLINE_TAG_START_LENGTH,
137	              -UNDERLINE_TAG_END_LENGTH,
138	            )}
139	          </Text>
140	        );
141	      } else if (fullMatch.match(/^https?:\/\//)) {
142	        renderedNode = (
143	          <Text key={key} color={theme.text.link}>
144	            {fullMatch}
145	          </Text>
146	        );
147	      }
148	    } catch (e) {
149	      debugLogger.warn('Error parsing inline markdown part:', fullMatch, e);
150	      renderedNode = null;
151	    }
152	
153	    nodes.push(
154	      renderedNode ?? (
155	        <Text key={key} color={baseColor}>
156	          {fullMatch}
157	        </Text>
158	      ),
159	    );
160	    lastIndex = inlineRegex.lastIndex;
161	  }
162	
163	  if (lastIndex < text.length) {
164	    nodes.push(
165	      <Text key={`t-${lastIndex}`} color={baseColor}>
166	        {text.slice(lastIndex)}
167	      </Text>,
168	    );
169	  }
170	
171	  return <>{nodes.filter((node) => node !== null)}</>;
172	};
173	
174	export const RenderInline = React.memo(RenderInlineInternal);
