22	interface TableRendererProps {
23	  headers: string[];
24	  rows: string[][];
25	  terminalWidth: number;
26	}
27	
28	const MIN_COLUMN_WIDTH = 5;
29	const COLUMN_PADDING = 2;
30	const TABLE_MARGIN = 2;
31	
32	const calculateWidths = (styledChars: StyledChar[]) => {
33	  const contentWidth = styledCharsWidth(styledChars);
34	
35	  const words: StyledChar[][] = wordBreakStyledChars(styledChars);
36	  const maxWordWidth = widestLineFromStyledChars(words);
37	
38	  return { contentWidth, maxWordWidth };
39	};
