41	// Used to reduce redundant parsing and cache the widths for each line
42	interface ProcessedLine {
43	  text: string;
44	  width: number;
45	}
46	
47	/**
48	 * Custom table renderer for markdown tables
49	 * We implement our own instead of using ink-table due to module compatibility issues
50	 */
51	export const TableRenderer: React.FC<TableRendererProps> = ({
52	  headers,
53	  rows,
54	  terminalWidth,
55	}) => {
56	  // Clean headers: remove bold markers since we already render headers as bold
57	  // and having them can break wrapping when the markers are split across lines.
58	  const cleanedHeaders = useMemo(
59	    () => headers.map((header) => header.replace(/\*\*(.*?)\*\*/g, '$1')),
60	    [headers],
61	  );
62	
63	  const styledHeaders = useMemo(
64	    () =>
65	      cleanedHeaders.map((header) =>
66	        toStyledCharacters(stripUnsafeCharacters(header)),
67	      ),
68	    [cleanedHeaders],
69	  );
70	
71	  const styledRows = useMemo(
72	    () =>
73	      rows.map((row) =>
74	        row.map((cell) => toStyledCharacters(stripUnsafeCharacters(cell))),
75	      ),
76	    [rows],
77	  );
78	
79	  const { wrappedHeaders, wrappedRows, adjustedWidths } = useMemo(() => {
80	    const numColumns = styledRows.reduce(
81	      (max, row) => Math.max(max, row.length),
82	      styledHeaders.length,
83	    );
84	
85	    // --- Define Constraints per Column ---
86	    const constraints = Array.from({ length: numColumns }).map(
87	      (_, colIndex) => {
88	        const headerStyledChars = styledHeaders[colIndex] || [];
89	        let { contentWidth: maxContentWidth, maxWordWidth } =
90	          calculateWidths(headerStyledChars);
91	
92	        styledRows.forEach((row) => {
93	          const cellStyledChars = row[colIndex] || [];
94	          const { contentWidth: cellWidth, maxWordWidth: cellWordWidth } =
95	            calculateWidths(cellStyledChars);
96	
97	          maxContentWidth = Math.max(maxContentWidth, cellWidth);
98	          maxWordWidth = Math.max(maxWordWidth, cellWordWidth);
99	        });
100	
101	        const minWidth = maxWordWidth;
102	        const maxWidth = Math.max(minWidth, maxContentWidth);
103	
104	        return { minWidth, maxWidth };
105	      },
106	    );
107	
108	    // --- Calculate Available Space ---
109	    // Fixed overhead: borders (n+1) + padding (2n)
110	    const fixedOverhead = numColumns + 1 + numColumns * COLUMN_PADDING;
111	    const availableWidth = Math.max(
112	      0,
113	      terminalWidth - fixedOverhead - TABLE_MARGIN,
114	    );
115	
116	    // --- Allocation Algorithm ---
117	    const totalMinWidth = constraints.reduce((sum, c) => sum + c.minWidth, 0);
118	    let finalContentWidths: number[];
119	
120	    if (totalMinWidth > availableWidth) {
121	      // We must scale all the columns except the ones that are very short(<=5 characters)
122	      const shortColumns = constraints.filter(
123	        (c) => c.maxWidth <= MIN_COLUMN_WIDTH,
124	      );
125	      const totalShortColumnWidth = shortColumns.reduce(
126	        (sum, c) => sum + c.minWidth,
127	        0,
128	      );
129	
130	      const finalTotalShortColumnWidth =
131	        totalShortColumnWidth >= availableWidth ? 0 : totalShortColumnWidth;
132	
133	      const scale =
134	        (availableWidth - finalTotalShortColumnWidth) /
135	        (totalMinWidth - finalTotalShortColumnWidth);
136	      finalContentWidths = constraints.map((c) => {
137	        if (c.maxWidth <= MIN_COLUMN_WIDTH && finalTotalShortColumnWidth > 0) {
138	          return c.minWidth;
139	        }
140	        return Math.floor(c.minWidth * scale);
141	      });
142	    } else {
143	      const surplus = availableWidth - totalMinWidth;
144	      const totalGrowthNeed = constraints.reduce(
145	        (sum, c) => sum + (c.maxWidth - c.minWidth),
146	        0,
147	      );
148	
149	      if (totalGrowthNeed === 0) {
150	        finalContentWidths = constraints.map((c) => c.minWidth);
151	      } else {
152	        finalContentWidths = constraints.map((c) => {
153	          const growthNeed = c.maxWidth - c.minWidth;
154	          const share = growthNeed / totalGrowthNeed;
155	          const extra = Math.floor(surplus * share);
156	          return Math.min(c.maxWidth, c.minWidth + extra);
157	        });
158	      }
159	    }
