161	    // --- Pre-wrap and Optimize Widths ---
162	    const actualColumnWidths = new Array(numColumns).fill(0);
163	
164	    const wrapAndProcessRow = (row: StyledChar[][]) => {
165	      const rowResult: ProcessedLine[][] = [];
