168	        const cellStyledChars = row[colIndex] || [];
169	        const allocatedWidth = finalContentWidths[colIndex];
170	        const contentWidth = Math.max(1, allocatedWidth);
171	
172	        const wrappedStyledLines = wrapStyledChars(
173	          cellStyledChars,
174	          contentWidth,
175	        );
176	
177	        const maxLineWidth = widestLineFromStyledChars(wrappedStyledLines);
178	        actualColumnWidths[colIndex] = Math.max(
179	          actualColumnWidths[colIndex],
180	          maxLineWidth,
181	        );
182	
183	        const lines = wrappedStyledLines.map((line) => ({
