193	    const wrappedRows = styledRows.map((row) => wrapAndProcessRow(row));
194	
195	    // Use the TIGHTEST widths that fit the wrapped content + padding
196	    const adjustedWidths = actualColumnWidths.map(
197	      (w) =>
198	        // eslint-disable-next-line @typescript-eslint/no-unsafe-return
199	        w + COLUMN_PADDING,
200	    );
201	
202	    return { wrappedHeaders, wrappedRows, adjustedWidths };
203	  }, [styledHeaders, styledRows, terminalWidth]);
