[metadata] {"type": "create", "filePath": "/workspace/repo/packages/cli/src/ui/utils/__scratch_md.test.tsx", "content": "/** scratch */
import { describe, it, expect } from 'vitest';
import { TableRenderer } from './TableRenderer.js';
import { parseMarkdownToANSI } from './InlineMarkdownRenderer.js';
import { renderWithProviders } from '../../test-utils/render.js';
import stripAnsi from 'strip-ansi';

const ESC = String.fromCharCode(27);

describe('scratch md', () => {
  it('parseMarkdownToANSI strips markers', () => {
    expect(stripAnsi(parseMarkdownToANSI('**bold**'))).toBe('bold');
    expect(stripAnsi(parseMarkdownToANSI('*it*'))).toBe('it');
    expect(stripAnsi(parseMarkdownToANSI('***bi***'))).toBe('bi');
    expect(stripAnsi(parseMarkdownToANSI('~~s~~'))).toBe('s');
    expect(stripAnsi(parseMarkdownToANSI('`code`'))).toBe('code');
    expect(stripAnsi(parseMarkdownToANSI('<u>u</u>'))).toBe('u');
    expect(stripAnsi(parseMarkdownToANSI('[G](https://g.com)'))).toBe(
      'G (https://g.com)',
    );
    expect(stripAnsi(parseMarkdownToANSI('plain text'))).toBe('plain text');
    expect(parseMarkdownToANSI('**bold**')).toContain(ESC + '[1m');
    expect(parseMarkdownToANSI('*it*')).toContain(ESC + '[3m');
    expect(parseMarkdownToANSI('~~s~~')).toContain(ESC + '[9m');
    expect(parseMarkdownToANSI('<u>u</u>')).toContain(ESC + '[4m');
  });

  it('table cell strips markdown and widths are visual', async () => {
    const r = renderWithProviders(
      <TableRenderer
        headers={['**H**', 'Plain']}
        rows={[['**cell**', 'x']]}
        terminalWidth={80}
      />,
    );
    await r.waitUntilReady();
    const out = r.lastFrame();

    console.log('FRAME:\n' + out);
    expect(out).not.toContain('**');
    expect(out).toContain('cell');
    expect(out).toContain('H');
    r.unmount();
  });
});
